            /// </summary>
            /// <param name="guid">the SDL_GUID you wish to get info about.</param>
            /// <param name="vendor">
            ///   a pointer filled in with the device VID, or 0 if not
            ///   available.
            /// </param>
            /// <param name="product">
            ///   a pointer filled in with the device PID, or 0 if not
            ///   available.
            /// </param>
            /// <param name="version">
            ///   a pointer filled in with the device version, or 0 if not
            ///   available.
            /// </param>
            /// <param name="crc16">
            ///   a pointer filled in with a CRC used to distinguish different
            ///   products with the same VID/PID, or 0 if not available.
            /// </param>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetJoystickGuidForID"/>
            public static void GetJoystickGuidInfo(
                SdlGuid guid,
                out ushort vendor,
                out ushort product,
                out ushort version,
                out ushort crc16
            )
            {
                vendor = default;
                product = default;
                version = default;
                crc16 = default;
                fixed (ushort* vendorPtr = &vendor)
                {
                    fixed (ushort* productPtr = &product)
                    {
                        fixed (ushort* versionPtr = &version)
                        {
                            fixed (ushort* crc16Ptr = &crc16)
                            {
                                PInvoke.GetJoystickGuidInfo(guid, vendorPtr, productPtr, versionPtr, crc16Ptr);
                            }
                        }
                    }
                }
            }

