            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetNumJoystickHats"/>
            public static byte GetJoystickHat(SdlJoystick joystick, int hat) => PInvoke.GetJoystickHat(joystick, hat);

            /// <summary>
            ///   Get the current state of a button on a joystick.
            /// </summary>
            /// <param name="joystick">an SDL_Joystick structure containing joystick information.</param>
            /// <param name="button">
            ///   the button index to get the state from; indices start at
            ///   index 0.
            /// </param>
            /// <returns>true if the button is pressed, false otherwise.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetNumJoystickButtons"/>
            public static bool GetJoystickButton(SdlJoystick joystick, int button) =>
                PInvoke.GetJoystickButton(joystick, button) != 0;

            /// <summary>
            ///   Start a rumble effect.
            /// </summary>
            /// <param name="joystick">the joystick to vibrate.</param>
            /// <param name="low_frequency_rumble">
            ///   the intensity of the low frequency (left)
            ///   rumble motor, from 0 to 0xFFFF.
            /// </param>
            /// <param name="high_frequency_rumble">
            ///   the intensity of the high frequency (right)
            ///   rumble motor, from 0 to 0xFFFF.
            /// </param>
            /// <param name="duration_ms">the duration of the rumble effect, in milliseconds.</param>
            /// <returns>true, or false if rumble isn't supported on this joystick.</returns>
            /// <remarks>
            ///   <para>
            ///     Each call to this function cancels any previous rumble effect, and calling
            ///     it with 0 intensity stops any rumbling.
            ///   </para>
            ///   <para>
            ///     This function requires you to process SDL events or call
            ///     SDL_UpdateJoysticks() to update rumble state.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool RumbleJoystick(
                SdlJoystick joystick,
                ushort low_frequency_rumble,
                ushort high_frequency_rumble,
                uint duration_ms
            ) => PInvoke.RumbleJoystick(joystick, low_frequency_rumble, high_frequency_rumble, duration_ms) != 0;

            /// <summary>
            ///   Start a rumble effect in the joystick's triggers.
            /// </summary>
            /// <param name="joystick">the joystick to vibrate.</param>
            /// <param name="left_rumble">
            ///   the intensity of the left trigger rumble motor, from 0
            ///   to 0xFFFF.
            /// </param>
            /// <param name="right_rumble">
            ///   the intensity of the right trigger rumble motor, from 0
            ///   to 0xFFFF.
            /// </param>
            /// <param name="duration_ms">the duration of the rumble effect, in milliseconds.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     Each call to this function cancels any previous trigger rumble effect, and
            ///     calling it with 0 intensity stops any rumbling.
            ///   </para>
            ///   <para>
            ///     Note that this is rumbling of the <em>triggers</em> and not the game controller as
            ///     a whole. This is currently only supported on Xbox One controllers. If you
            ///     want the (more common) whole-controller rumble, use SDL_RumbleJoystick()
            ///     instead.
            ///   </para>
            ///   <para>
            ///     This function requires you to process SDL events or call
            ///     SDL_UpdateJoysticks() to update rumble state.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RumbleJoystick"/>
            public static bool RumbleJoystickTriggers(
                SdlJoystick joystick,
                ushort left_rumble,
                ushort right_rumble,
                uint duration_ms
            ) => PInvoke.RumbleJoystickTriggers(joystick, left_rumble, right_rumble, duration_ms) != 0;

            /// <summary>
            ///   Update a joystick's LED color.
            /// </summary>
            /// <param name="joystick">the joystick to update.</param>
            /// <param name="red">the intensity of the red LED.</param>
            /// <param name="green">the intensity of the green LED.</param>
            /// <param name="blue">the intensity of the blue LED.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     An example of a joystick LED is the light on the back of a PlayStation 4's
            ///     DualShock 4 controller.
            ///   </para>
            ///   <para>
            ///     For joysticks with a single color LED, the maximum of the RGB values will
            ///     be used as the LED brightness.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool SetJoystickLED(SdlJoystick joystick, byte red, byte green, byte blue) =>
                PInvoke.SetJoystickLED(joystick, red, green, blue) != 0;

            /// <summary>
            ///   Send a joystick specific effect packet.
            /// </summary>
            /// <param name="joystick">the joystick to affect.</param>
            /// <param name="data">the data to send to the joystick.</param>
            /// <param name="size">the size of the data to send to the joystick.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool SendJoystickEffect(SdlJoystick joystick, void* data, int size) =>
                PInvoke.SendJoystickEffect(joystick, data, size) != 0;

            /// <summary>
            ///   Close a joystick previously opened with SDL_OpenJoystick().
            /// </summary>
            /// <param name="joystick">the joystick device to close.</param>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.OpenJoystick"/>
            public static void CloseJoystick(SdlJoystick joystick) => PInvoke.CloseJoystick(joystick);

            /// <summary>
            ///   Get the connection state of a joystick.
            /// </summary>
            /// <param name="joystick">the joystick to query.</param>
            /// <returns>
            ///   the connection state on success or
            ///   <c>SDL_JOYSTICK_CONNECTION_INVALID</c> on failure; call SDL_GetError()
            ///   for more information.
            /// </returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static SdlJoystickConnectionState GetJoystickConnectionState(SdlJoystick joystick) =>
                PInvoke.GetJoystickConnectionState(joystick);

            /// <summary>
            ///   Get the battery state of a joystick.
            /// </summary>
            /// <param name="joystick">the joystick to query.</param>
            /// <param name="percent">
            ///   a pointer filled in with the percentage of battery life
            ///   left, between 0 and 100, or NULL to ignore. This will be
            ///   filled in with -1 we can't determine a value or there is no
            ///   battery.
            /// </param>
            /// <returns>
            ///   the current battery state or <c>SDL_POWERSTATE_ERROR</c> on failure;
            ///   call SDL_GetError() for more information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     You should never take a battery status as absolute truth. Batteries
            ///     (especially failing batteries) are delicate hardware, and the values
            ///     reported here are best estimates based on what that hardware reports. It's
            ///     not uncommon for older batteries to lose stored power much faster than it
            ///     reports, or completely drain when reporting it has 20 percent left, etc.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static SdlPowerState GetJoystickPowerInfo(SdlJoystick joystick, out int percent)
            {
                percent = default;
                fixed (int* percentPtr = &percent)
                {
                    return PInvoke.GetJoystickPowerInfo(joystick, percentPtr);
                }
            }
        }
    }
}
